from itertools import combinations
import sys

edges = []
for g in range(3):
    for i,j in combinations(range(4),2):
        edges.append((4*g+i, 4*g+j))
for g in range(2):
    for i in range(4):
        edges.append((4*g+i, 4*(g+1)+i))

adj = [[] for _ in range(12)]
for u,v in edges:
    adj[u].append(v)
    adj[v].append(u)

order = [0]
visited = {0}
while len(order) < 12:
    best = -1; bv = -1
    for v in range(12):
        if v in visited: continue
        c = sum(1 for u in adj[v] if u in visited)
        if c > bv:
            bv = c; best = v
    order.append(best)
    visited.add(best)
print("order", order)

pos_of = {v:i for i,v in enumerate(order)}
prev_edges = [[] for _ in range(12)]
for i,v in enumerate(order):
    for u in adj[v]:
        if pos_of[u] < i:
            prev_edges[i].append(pos_of[u])

labels = [0]*12
used_labels = [False]*27
used_diffs = [False]*27

state = {'sol': None, 'count':0}

def bt(i):
    if state['sol'] is not None:
        return
    state['count']+=1
    if i == 12:
        state['sol'] = labels[:]
        return
    for lab in range(27):
        if used_labels[lab]: continue
        new_diffs = []
        ok = True
        for p in prev_edges[i]:
            d = abs(lab - labels[p])
            if used_diffs[d] or d in new_diffs:
                ok = False; break
            new_diffs.append(d)
        if not ok: continue
        labels[i] = lab
        used_labels[lab] = True
        for d in new_diffs:
            used_diffs[d] = True
        bt(i+1)
        if state['sol'] is not None:
            return
        for d in new_diffs:
            used_diffs[d] = False
        used_labels[lab] = False

sys.setrecursionlimit(10000)
bt(0)
print("count", state['count'])
if state['sol']:
    labels_by_vertex = [0]*12
    for i,v in enumerate(order):
        labels_by_vertex[v] = state['sol'][i]
    print(labels_by_vertex)
    diffs = [abs(labels_by_vertex[u]-labels_by_vertex[v]) for u,v in edges]
    print(sorted(diffs))
    print(len(set(diffs)) == len(diffs))

